param()
$ErrorActionPreference='Stop'
Add-Type -AssemblyName PresentationCore,PresentationFramework,WindowsBase
$reviewRoot=Split-Path -Parent $PSScriptRoot
function Read-ReviewImage([string]$relative){$s=[IO.File]::OpenRead((Join-Path $reviewRoot $relative));try{$b=[Windows.Media.Imaging.BitmapImage]::new();$b.BeginInit();$b.CacheOption='OnLoad';$b.StreamSource=$s;$b.EndInit();$b.Freeze();return $b}finally{$s.Dispose()}}
function Save-ReviewVisual($visual,[int]$width,[int]$height,[string]$relative){$b=[Windows.Media.Imaging.RenderTargetBitmap]::new($width,$height,96,96,[Windows.Media.PixelFormats]::Pbgra32);$b.Render($visual);$e=[Windows.Media.Imaging.PngBitmapEncoder]::new();$e.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($b));$s=[IO.File]::Create((Join-Path $reviewRoot $relative));try{$e.Save($s)}finally{$s.Dispose()}}
function Draw-ReviewLabel($context,[string]$label,[double]$x,[double]$y){$t=[Windows.Media.FormattedText]::new($label,[Globalization.CultureInfo]::GetCultureInfo('zh-CN'),[Windows.FlowDirection]::LeftToRight,[Windows.Media.Typeface]::new('Microsoft YaHei UI'),16,[Windows.Media.Brushes]::Black,1.0);$context.DrawText($t,[Windows.Point]::new($x,$y))}
$source=Read-ReviewImage 'design/ui/轻透主题/01-暖香槟-默认.png';$source=[Windows.Media.Imaging.CroppedBitmap]::new($source,[Windows.Int32Rect]::new(52,122,1004,820));$current=Read-ReviewImage 'artifacts/design-v03/audit/01-home.png'
$v=[Windows.Media.DrawingVisual]::new();$c=$v.RenderOpen();$c.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,2056,900));Draw-ReviewLabel $c '已选效果图' 12 12;Draw-ReviewLabel $c '当前发布程序 / 本轮新截取' 1040 12;$c.DrawImage($source,[Windows.Rect]::new(12,44,1004,820));$c.DrawImage($current,[Windows.Rect]::new(1040,44,1004,(1004.0*$current.PixelHeight/$current.PixelWidth)));$c.Close();Save-ReviewVisual $v 2056 900 'artifacts/design-v03/audit/10-reference-comparison.png'
$groups=@(@('01-home','03-medicine','05-history'),@('02-plan-editor','04-medicine-editor','09-meeting'),@('06-settings','07-appearance','08-reminder'))
for($g=0;$g -lt $groups.Count;$g++){$v=[Windows.Media.DrawingVisual]::new();$c=$v.RenderOpen();$c.DrawRectangle([Windows.Media.Brushes]::White,$null,[Windows.Rect]::new(0,0,1656,680));for($i=0;$i -lt 3;$i++){$name=$groups[$g][$i];$b=Read-ReviewImage ('artifacts/design-v03/audit/'+$name+'.png');$fit=[Math]::Min(520.0/$b.PixelWidth,600.0/$b.PixelHeight);$x=12+$i*552;Draw-ReviewLabel $c $name $x 12;$c.DrawImage($b,[Windows.Rect]::new($x,44,$b.PixelWidth*$fit,$b.PixelHeight*$fit))};$c.Close();Save-ReviewVisual $v 1656 680 ('artifacts/design-v03/audit/11-flow-'+($g+1)+'.png')}
Write-Output 'Fresh comparison and three audit contact sheets rendered.'
